private void btnEvaluateActionPerformed(java.awt.event.ActionEvent evt) {
    try {
        // Step 1: Read marks
        double m1 = Double.parseDouble(txtMarks1.getText().trim());
        double m2 = Double.parseDouble(txtMarks2.getText().trim());
        double m3 = Double.parseDouble(txtMarks3.getText().trim());

        // Validation
        if (m1 < 0 || m1 > 100 || m2 < 0 || m2 > 100 || m3 < 0 || m3 > 100) {
            javax.swing.JOptionPane.showMessageDialog(this, 
                "Marks must be between 0 and 100!", "Range Error", 
                javax.swing.JOptionPane.WARNING_MESSAGE);
            return;
        }

        // Step 2: Compute percentage
        double total = m1 + m2 + m3;
        double percentage = (total / 300.0) * 100.0;

        // Step 3: Determine Grade
        String grade;
        if (percentage >= 85) {
            grade = "A (Distinction)";
        } else if (percentage >= 65) {
            grade = "B (First Class)";
        } else if (percentage >= 40) {
            grade = "C (Pass)";
        } else {
            grade = "D (Needs Improvement)";
        }

        // Step 4: Display results
        lblPercentage.setText(String.format("%.2f %%", percentage));
        lblGrade.setText(grade);

    } catch (NumberFormatException ex) {
        javax.swing.JOptionPane.showMessageDialog(this, 
            "Please enter valid numeric marks in all fields!", 
            "Error", javax.swing.JOptionPane.ERROR_MESSAGE);
    }
}
```

